// Store incoming MQTT reading, maintain rolling history, and run edge intelligence.
var d = msg.payload || {};

if (typeof d.temperature !== 'number' || typeof d.humidity !== 'number') {
    return [null];
}

// ESP32 publishes LDR as a raw ADC value (0-4095).
// Convert it to a percentage for the dashboard while retaining the raw value.
var lightRaw = (typeof d.light === 'number') ? d.light : 0;
var lightPct = (typeof d.lightPct === 'number') ? d.lightPct : Math.round((lightRaw / 4095) * 100);
lightPct = Math.max(0, Math.min(100, lightPct));

var reading = {
    deviceId: d.deviceId || "Wokwi-ESP32",
    temperature: d.temperature,
    humidity: d.humidity,
    motion: (d.motion === 1 || d.motion === true) ? 1 : 0,
    lightRaw: lightRaw,
    lightPct: lightPct,
    ts: Date.now()
};

var history = flow.get('history') || [];
history.push(reading);
if (history.length > 100) history.shift();
flow.set('history', history);
flow.set('latest', reading);

// Edge intelligence: combine environmental deviation, trends, and access anomaly.
var prevWindow = history.slice(-4);
var tempSeries = prevWindow.map(function(r){ return r.temperature; });
var humSeries  = prevWindow.map(function(r){ return r.humidity; });
var tempTrend = tempSeries.length > 1 ? (tempSeries[tempSeries.length-1] - tempSeries[0]) / (tempSeries.length-1) : 0;
var humTrend  = humSeries.length > 1 ? (humSeries[humSeries.length-1] - humSeries[0]) / (humSeries.length-1) : 0;

var TEMP_LOW = 18, TEMP_HIGH = 27;
var HUM_LOW = 40, HUM_HIGH = 60;
var LIGHT_LOW = 49; // approximately 2000/4095 converted to percent

function bandDeviation(val, low, high) {
    if (val < low) return low - val;
    if (val > high) return val - high;
    return 0;
}

var tempDev = bandDeviation(reading.temperature, TEMP_LOW, TEMP_HIGH);
var humDev  = bandDeviation(reading.humidity, HUM_LOW, HUM_HIGH);
var prevLight = history.length > 1 ? history[history.length-2].lightPct : reading.lightPct;
var lightJump = reading.lightPct - prevLight;
var accessAnomaly = (reading.motion === 1 && lightJump > 15) ? 1 : 0;
var thermalRunaway = (tempTrend > 0.3 && humTrend > 0.5) ? 1 : 0;

var score = 0;
score += Math.min(tempDev * 8, 40);
score += Math.min(humDev * 3, 20);
score += thermalRunaway ? 20 : 0;
score += accessAnomaly ? 15 : 0;
score += Math.min(Math.max(tempTrend,0) * 10, 5);
score = Math.max(0, Math.min(100, Math.round(score)));

var level;
if (score < 20) level = "LOW";
else if (score < 45) level = "MEDIUM";
else if (score < 70) level = "HIGH";
else level = "CRITICAL";

var cooling;
if (reading.temperature > TEMP_HIGH && reading.humidity > HUM_HIGH) {
    cooling = "Increase cooling AND dehumidify - high thermal + moisture load";
} else if (thermalRunaway) {
    cooling = "Preemptively increase cooling - rising trend suggests HVAC lag";
} else if (reading.temperature > TEMP_HIGH) {
    cooling = "Increase cooling";
} else if (reading.temperature < TEMP_LOW) {
    cooling = "Reduce cooling - room overcooled, save energy";
} else if (reading.humidity > HUM_HIGH) {
    cooling = "Run dehumidifier - temperature OK but humidity elevated";
} else if (reading.motion === 0 && reading.lightPct < LIGHT_LOW) {
    cooling = "Normal - maintain current HVAC settings";
} else {
    cooling = "Normal - maintain current HVAC settings";
}

var risk = {
    score: score,
    level: level,
    cooling: cooling,
    tempTrend: Number(tempTrend.toFixed(2)),
    humTrend: Number(humTrend.toFixed(2)),
    accessAnomaly: accessAnomaly,
    thermalRunaway: thermalRunaway,
    ts: Date.now()
};
flow.set('risk', risk);

if (level === "HIGH" || level === "CRITICAL") {
    flow.set('alertActive', true);
}

var dash = { reading: reading, risk: risk };
return [dash];

var out1 = { payload: msg.payload.reading.temperature };            // temp gauge
var out2 = { payload: msg.payload.reading.humidity };                // humidity gauge
var out3 = { payload: msg.payload.reading.lightPct };                 // light gauge
var out4 = { payload: msg.payload.reading.motion ? "Motion Detected" : "No Motion" }; // motion text
var out5 = { payload: { temperature: msg.payload.reading.temperature, humidity: msg.payload.reading.humidity } }; // chart (multi-series via 2 msgs below instead)
var out6 = { payload: msg.payload.risk.level + " (" + msg.payload.risk.score + "/100)" }; // risk text
var out7 = { payload: msg.payload.risk.cooling };                     // cooling recommendation
var out8 = null;
if (msg.payload.risk.level === "HIGH" || msg.payload.risk.level === "CRITICAL") {
    out8 = { payload: "\u26A0 " + msg.payload.risk.level + " RISK: " + msg.payload.risk.cooling };
}
var tempPoint = { payload: msg.payload.reading.temperature, topic: "Temperature" };
var humPoint  = { payload: msg.payload.reading.humidity, topic: "Humidity" };
return [out1, out2, out3, out4, [tempPoint, humPoint], out6, out7, out8];

msg.payload = flow.get('latest') || {};
msg.statusCode = msg.payload.ts ? 200 : 204;
return msg;

var n = Number(msg.req.query.limit) || 20;
var hist = flow.get('history') || [];
msg.payload = hist.slice(-n);
msg.statusCode = 200;
return msg;

msg.payload = flow.get('risk') || { level: 'UNKNOWN', score: 0, cooling: 'No data yet' };
msg.statusCode = 200;
return msg;

flow.set('alertActive', false);
msg.statusCode = 200;
msg.payload = { status: 'acknowledged', ts: Date.now() };
return msg;
